let lastTopic = "";

return items.flatMap(item => {
  const topic = item.json.topic?.trim() || lastTopic;
  const rawUrls = item.json.source_url?.trim();

  if (!topic || !rawUrls) return [];

  lastTopic = topic;

  const urls = rawUrls
    .split(/\r?\n+/) // handles newlines
    .map(u => u.trim())
    .filter(u => u.startsWith("http"));

  return urls.map(url => ({
    json: {
      topic,
      source_url: url
    }
  }));
});

// Each incoming item should look like:
// { json: { topic, source_url, results: [ { text, keywordIdeaMetrics: {...} }, ... ] } }

const out = [];

for (const item of items) {
  const { topic, source_url, results = [] } = item.json;

  for (const r of results) {
    const m = r.keywordIdeaMetrics || {};

    out.push({
      json: {
        topic,
        source_url,
        keyword: r.text,
        avg_monthly_searches: Number(m.avgMonthlySearches ?? 0),
        competition: m.competition || '',
        competition_index: Number(m.competitionIndex ?? 0),

        // Convert micros → currency units (e.g., USD)
        low_top_of_page_bid: Math.round((Number(m.lowTopOfPageBidMicros || 0) / 1e6) * 100) / 100,
        high_top_of_page_bid: Math.round((Number(m.highTopOfPageBidMicros || 0) / 1e6) * 100) / 100,

        // Optional: keep last 12 months in a compact string for quick review
        last12mo_searches: (m.monthlySearchVolumes || [])
          .map(v => `${v.month}-${v.year}:${v.monthlySearches}`)
          .join(' | ')
      }
    });
  }
}

return out;

const filteredItems = [];

for (const item of $input.all()) {
  const keyword = item.json.keyword.toLowerCase();
  const avgVolume = parseInt(item.json.avg_monthly_searches);
  const lowBid = parseFloat(item.json.low_top_of_page_bid);
  const highBid = parseFloat(item.json.high_top_of_page_bid);
  const avgBid = (lowBid + highBid) / 2;

  // AI-related detection
  const aiTerms = ['ai', 'artificial intelligence', 'artificial-intelligence',
                   'intelligent', "artificial", 'chatbot', 'bot', 'digital assistant'];
  const isAiKeyword = aiTerms.some(term => keyword.includes(term));

  // Elite rules for pillar
  if (
    avgVolume >= 500 ||                      // strong volume
    (avgVolume >= 200 && avgBid >= 300) ||   // mid-volume but strong commercial
    (isAiKeyword && avgVolume >= 100)        // AI override if min volume met
  ) {
    item.json.isAiKeyword = isAiKeyword;
    item.json.avgBid = Math.round(avgBid);

    // Classification
    item.json.keywordType = 
      isAiKeyword ? "AI_PROTECTED" :
      avgVolume >= 5000 ? "ULTRA_VOLUME" :
      avgVolume >= 1000 ? "HIGH_VOLUME" :
      avgBid >= 300 ? "COMMERCIAL_VALUE" : "QUALIFIED";

    filteredItems.push(item);
  }
}

return filteredItems;

const filteredItems = [];

for (const item of $input.all()) {
  const competitionIndex = parseInt(item.json.competition_index);
  const isAiKeyword = item.json.isAiKeyword || false;

  const avgBid = item.json.avgBid || (() => {
    const lowBid = parseFloat(item.json.low_top_of_page_bid);
    const highBid = parseFloat(item.json.high_top_of_page_bid);
    return (lowBid + highBid) / 2;
  })();

  const bidSpread = parseFloat(item.json.high_top_of_page_bid) - parseFloat(item.json.low_top_of_page_bid);

  let competitionTier;
  let shouldKeep = false;

  if (competitionIndex <= 40 && avgBid < 150) {
    competitionTier = "EASY_WIN";
    shouldKeep = true;
  } else if (competitionIndex <= 60 && avgBid < 400) {
    competitionTier = "SWEET_SPOT";
    shouldKeep = true;
  } else if (competitionIndex <= 70 && bidSpread < 800) {
    competitionTier = "PILLAR_WORTHY_OPPORTUNITY"; // for pillar we allow up to 70
    shouldKeep = true;
  }

  // AI override
  if (isAiKeyword && competitionIndex <= 80) {
    shouldKeep = true;
    if (competitionIndex > 70) competitionTier = "AI_PROTECTED_HARD";
  }

  if (shouldKeep) {
    item.json.competitionTier = competitionTier;
    item.json.competitionIndex = competitionIndex;
    item.json.avgBid = Math.round(avgBid);
    item.json.bidSpread = Math.round(bidSpread);

    item.json.commercialScore = avgBid >= 500 ? 25 :
                               avgBid >= 300 ? 20 :
                               avgBid >= 150 ? 15 : 10;

    filteredItems.push(item);
  }
}

return filteredItems;

const filteredItems = [];

for (const item of $input.all()) {
  const lastMonths = item.json.last12mo_searches;
  const isAiKeyword = item.json.isAiKeyword || false;
  const competitionIndex = parseInt(item.json.competition_index);

  const avgBid = item.json.avgBid || (() => {
    const lowBid = parseFloat(item.json.low_top_of_page_bid);
    const highBid = parseFloat(item.json.high_top_of_page_bid);
    return (lowBid + highBid) / 2;
  })();

  if (!lastMonths || !lastMonths.match) continue;

  const volumeMatches = lastMonths.match(/(\w+-\d{4}):(\d+)/g);
  if (!volumeMatches || volumeMatches.length < 6) continue;

  const volumes = volumeMatches.map(match => parseInt(match.split(':')[1]));
  const recent3 = volumes.slice(-3);
  const first3 = volumes.slice(0, 3);

  const recentAvg = recent3.reduce((a, b) => a + b, 0) / 3;
  const firstAvg = first3.reduce((a, b) => a + b, 0) / 3;

  const trendPercent = firstAvg > 0 ? ((recentAvg - firstAvg) / firstAvg) * 100 : 0;

  let trendDirection;
  if (trendPercent > 10) trendDirection = "GROWING";
  else if (trendPercent < -20) trendDirection = "DECLINING";
  else trendDirection = "STABLE";

  let marketOpportunity;
  if (trendDirection === "GROWING" && competitionIndex <= 70 && avgBid >= 200) {
    marketOpportunity = "GOLDMINE";
  } else if (trendDirection === "GROWING" && avgBid < 100) {
    marketOpportunity = "EMERGING_NICHE";
  } else if (trendDirection === "STABLE" && competitionIndex <= 50) {
    marketOpportunity = "CONSISTENT";
  } else if (trendDirection === "DECLINING" && avgBid >= 500 && isAiKeyword) {
    marketOpportunity = "HIGH_VALUE_DECLINING_AI";
  } else {
    marketOpportunity = "STANDARD";
  }

  if (
    trendDirection === "GROWING" ||
    (trendDirection === "STABLE" && competitionIndex <= 50) ||
    (trendDirection === "DECLINING" && marketOpportunity.includes("AI"))
  ) {
    item.json.trendDirection = trendDirection;
    item.json.trendPercent = Math.round(trendPercent);
    item.json.marketOpportunity = marketOpportunity;

    filteredItems.push(item);
  }
}

return filteredItems;

// Build a single batch object that carries all keywords WITH metrics
const allItems = $input.all();

const keywords = allItems.map(({ json }) => {
  // fallback helpers
  const avgMonthly = json.avg_monthly_searches ?? json.avgMonthlySearches ?? 0;
  const compIdx = json.competition_index ?? json.competitionIndex ?? 0;

  // avgBid fallback to midpoint of low/high bid if missing
  const lowBid = json.low_top_of_page_bid ?? 0;
  const highBid = json.high_top_of_page_bid ?? 0;
  const avgBid =
    json.avgBid != null
      ? json.avgBid
      : (Number(lowBid) + Number(highBid)) / 2;

  return {
    keyword: json.keyword,
    avg_monthly_searches: Number(avgMonthly),
    competition_index: Number(compIdx),
    avgBid: Number(avgBid),
    competitionTier: json.competitionTier ?? null,
    commercialScore: json.commercialScore ?? null,
    trendDirection: json.trendDirection ?? null,
    marketOpportunity: json.marketOpportunity ?? null,
  };
});

return [
  {
    keywords,                 // array of keyword objects with required fields
    totalKeywords: keywords.length,
  },
];

